package com.stocksentinel;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import com.stocksentinel.custom.CustomRuleEngine;
import static com.stocksentinel.custom.CustomRuleEngine.*;
import java.math.BigDecimal;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class CustomRuleEngineTest {
    static final ObjectMapper JSON=new ObjectMapper();
    static ObjectNode definition(){try{return (ObjectNode)JSON.readTree("""
      {"schemaVersion":"1","adjustment":"QFQ","universe":"SYMBOLS","symbols":["000731"],"rules":{"logic":"AND","children":[{"factor":"CLOSE","operator":"GT","operand":{"factor":"MA20"}},{"factor":"VOLUME_RATIO","operator":"GE","operand":{"value":1.5}}]}}
      """);}catch(Exception e){throw new IllegalStateException(e);}}
    Map<Factor,Value> values(){return Map.of(Factor.CLOSE,new Value(new BigDecimal("10"),new BigDecimal("9")),Factor.MA20,new Value(new BigDecimal("9.5"),new BigDecimal("9")),Factor.VOLUME_RATIO,new Value(new BigDecimal("1.5"),BigDecimal.ONE));}
    @Test void factorComparisonsAndInclusiveDecimalThresholds(){var result=evaluate(definition(),values());assertEquals("MATCHED",result.status());assertEquals("PASS",result.conditions().get(1).get("status"));}
    @Test void numericComparisonNeverUsesLexicalOrdering(){var d=definition();((ArrayNode)d.at("/rules/children")).remove(1);((ObjectNode)d.at("/rules/children/0/operand")).remove("factor");((ObjectNode)d.at("/rules/children/0/operand")).put("value",2);assertEquals("MATCHED",evaluate(d,values()).status());}
    @Test void crossRequiresBothDatesAndEqualityDoesNotRepeat(){var d=definition();((ArrayNode)d.at("/rules/children")).remove(1);((ObjectNode)d.at("/rules/children/0")).put("operator","CROSS_UP");assertEquals("MATCHED",evaluate(d,values()).status());var map=new EnumMap<Factor,Value>(values());map.put(Factor.CLOSE,new Value(BigDecimal.TEN,BigDecimal.TEN));assertEquals("NO_MATCH",evaluate(d,map).status());map.put(Factor.CLOSE,new Value(BigDecimal.TEN,null));assertEquals("SKIPPED",evaluate(d,map).status());}
    @Test void missingFactorCannotBeBypassedByAnotherTrueOrBranch(){var d=definition();((ObjectNode)d.path("rules")).put("logic","OR");var values=new EnumMap<Factor,Value>(values());values.remove(Factor.VOLUME_RATIO);assertEquals("SKIPPED",evaluate(d,values).status());assertEquals("MISSING",evaluate(d,values).conditions().get(1).get("status"));}
    @Test void risingUsesPreviousValueInExplanation(){var d=definition();var children=(ArrayNode)d.at("/rules/children");children.removeAll();children.addObject().put("factor","CLOSE").put("operator","RISING");var result=evaluate(d,values());assertEquals("MATCHED",result.status());assertEquals(new BigDecimal("9"),result.conditions().getFirst().get("threshold"));}
    @Test void incompatibleUnitsAndUnknownFieldsAreRejected(){var d=definition();((ObjectNode)d.at("/rules/children/0/operand")).put("factor","VOLUME");assertThrows(IllegalArgumentException.class,()->validate(d));var unknown=definition().put("script","1+1");assertThrows(IllegalArgumentException.class,()->validate(unknown));var injected=definition();((ObjectNode)injected.at("/rules/children/0")).put("factor","close_price; DROP TABLE stock_info");assertThrows(IllegalArgumentException.class,()->validate(injected));}
    @Test void limitsAndUnsupportedUniverseAreEnforced(){var d=definition();d.put("universe","ALL");assertThrows(IllegalArgumentException.class,()->validate(d));var tooMany=definition();var children=(ArrayNode)tooMany.at("/rules/children");var leaf=children.get(0).deepCopy();for(int i=0;i<20;i++)children.add(leaf);assertThrows(IllegalArgumentException.class,()->validate(tooMany));var duplicate=definition();((ArrayNode)duplicate.path("symbols")).add("000731");assertThrows(IllegalArgumentException.class,()->validate(duplicate));}
    @Test void nestedAndOrIsEvaluatedAndThirdLevelIsRejected(){var d=definition();var children=(ArrayNode)d.at("/rules/children");var group=children.addObject();group.put("logic","OR");group.putArray("children").add(children.get(0).deepCopy());assertEquals("MATCHED",evaluate(d,values()).status());var nested=((ArrayNode)group.path("children")).addObject();nested.put("logic","AND").putArray("children").add(children.get(0).deepCopy());assertThrows(IllegalArgumentException.class,()->validate(d));}
    @Test void constantMagnitudeAndOperandShapesAreBounded(){var d=definition();((ObjectNode)d.at("/rules/children/1/operand")).put("value",new BigDecimal("1e100"));assertThrows(IllegalArgumentException.class,()->validate(d));var invalid=definition();((ObjectNode)invalid.at("/rules/children/0/operand")).put("value",1);assertThrows(IllegalArgumentException.class,()->validate(invalid));}
}
